#include <furi.h>
#include <gui/gui.h>
#include <input/input.h>
#include <stdlib.h>
#include <stdio.h>
#define W 256
#define H 64
typedef struct {uint8_t map[H][W]; int x,y,v,dir,stock; bool build,run; FuriMutex* lock; FuriMessageQueue* q;} Game;
static bool solid(Game*g,int x,int y){return x<0||x>=W||y>=H||(y>=0&&g->map[y][x]);}
static void draw(Canvas*c,void*p){Game*g=p;furi_mutex_acquire(g->lock,FuriWaitForever);canvas_clear(c);int ox=g->x-15,oy=g->y-7;for(int j=0;j<14;j++)for(int i=0;i<32;i++){int x=ox+i,y=oy+j;if(x>=0&&x<W&&y>=0&&y<H&&g->map[y][x]){int a=i*4,b=j*4+8;canvas_draw_box(c,a,b,4,4);if(g->map[y][x]==1){canvas_set_color(c,ColorWhite);canvas_draw_dot(c,a+1,b+1);canvas_set_color(c,ColorBlack);}}}canvas_draw_frame(c,60,32,4,4);canvas_draw_box(c,60,36,4,4);canvas_draw_dot(c,61,40);canvas_draw_dot(c,63,40);char s[40];snprintf(s,sizeof(s),"%s Blocks:%d",g->build?"BUILD":"MINE",g->stock);canvas_set_font(c,FontSecondary);canvas_draw_str(c,0,7,s);furi_mutex_release(g->lock);}
static void input(InputEvent*e,void*p){Game*g=p;furi_message_queue_put(g->q,e,0);}
int32_t terraria_app(void*ctx){UNUSED(ctx);Game*g=calloc(1,sizeof(Game));if(!g)return -1;g->lock=furi_mutex_alloc(FuriMutexTypeNormal);g->q=furi_message_queue_alloc(16,sizeof(InputEvent));int ground=24;for(int x=0;x<W;x++){if(x%4==0)ground+=(rand()%3)-1;if(ground<18)ground=18;if(ground>30)ground=30;for(int y=ground;y<H;y++)g->map[y][x]=y<ground+5?1:2;}g->x=16;g->y=10;g->dir=1;g->run=true;Gui*gui=furi_record_open(RECORD_GUI);ViewPort*vp=view_port_alloc();view_port_draw_callback_set(vp,draw,g);view_port_input_callback_set(vp,input,g);gui_add_view_port(gui,vp,GuiLayerFullscreen);while(g->run){InputEvent e;bool got=furi_message_queue_get(g->q,&e,33)==FuriStatusOk;furi_mutex_acquire(g->lock,FuriWaitForever);if(got&&(e.type==InputTypePress||e.type==InputTypeRepeat)){if(e.key==InputKeyBack)g->run=false;if(e.key==InputKeyDown)g->build=!g->build;if(e.key==InputKeyLeft||e.key==InputKeyRight){g->dir=e.key==InputKeyLeft?-1:1;if(!solid(g,g->x+g->dir,g->y)&&!solid(g,g->x+g->dir,g->y-1))g->x+=g->dir;}if(e.key==InputKeyUp&&solid(g,g->x,g->y+1))g->v=-3;if(e.key==InputKeyOk){int x=g->x+g->dir,y=g->y+1;if(x>=0&&x<W&&y>=0&&y<H){if(g->build&&g->stock&&!g->map[y][x]){g->map[y][x]=1;g->stock--;}else if(!g->build&&g->map[y][x]){g->map[y][x]=0;g->stock++;}}}}if(g->v<1)g->v++;int d=g->v<0?-1:1;for(int i=0;i<abs(g->v);i++){if(solid(g,g->x,g->y+d)){g->v=0;break;}g->y+=d;}furi_mutex_release(g->lock);view_port_update(vp);}gui_remove_view_port(gui,vp);view_port_free(vp);furi_record_close(RECORD_GUI);furi_message_queue_free(g->q);furi_mutex_free(g->lock);free(g);return 0;}